      totalItems,
      totalValue,
      lowStockCount: lowStockItems.length,
      outOfStockCount: outOfStockItems.length,
      categoryDistribution,
      categoryValues,
      lowStockItems: lowStockItems.map(item => ({
        item: item.item,
        current: item.quantity,
        minimum: item.minStock,
        supplier: item.supplier
      }))
    };
  }
