    const revenueGrowth = this.calculateRevenueGrowth(finance.monthlyBreakdown);
    return {
      profitMargin,
      revenueGrowth,
      expenseRatio: (finance.totalExpenses / finance.totalRevenue * 100).toFixed(1),
      healthScore: this.calculateFinancialHealthScore(finance)
    };
  }
  calculateRevenueGrowth(monthlyData) {
    if (monthlyData.length < 2) return 0;
    const recent = monthlyData.slice(-3);
    const older = monthlyData.slice(-6, -3);
    const recentAvg = recent.reduce((sum, m) => sum + m.income, 0) / recent.length;
    const olderAvg = older.reduce((sum, m) => sum + m.income, 0) / older.length;
    return ((recentAvg - olderAvg) / olderAvg * 100).toFixed(1);
  }
  calculateFinancialHealthScore(finance) {
    const profitMargin = finance.netProfit / finance.totalRevenue * 100;
    if (profitMargin > 20) return 'Excellent';
    if (profitMargin > 15) return 'Good';
    if (profitMargin > 10) return 'Fair';
    return 'Needs Improvement';
  }
  calculateAttendanceTrends(students) {
    const attendanceRanges = {
      'Excellent (95%+)': students.filter(s => s.attendance.percentage >= 95).length,
      'Good (90-94%)': students.filter(s => s.attendance.percentage >= 90 && s.attendance.percentage < 95).length,
      'Fair (80-89%)': students.filter(s => s.attendance.percentage >= 80 && s.attendance.percentage < 90).length,
      'Poor (<80%)': students.filter(s => s.attendance.percentage < 80).length
    };
    return attendanceRanges;
  }
  getTopPerformers(students, count = 5) {
    return students.map(s => ({
      name: s.name,
      grade: s.grade,
      average: parseFloat(this.calculateAverageGrade(s.grades))
    })).sort((a, b) => b.average - a.average).slice(0, count);
  }
  getStudentsNeedingAttention(students) {
    return students.filter(s => {
      const avgGrade = parseFloat(this.calculateAverageGrade(s.grades));
      return avgGrade < 70 || s.attendance.percentage < 85 || s.fees.pending > 0;
    }).map(s => ({
      name: s.name,
      grade: s.grade,
      issues: [...(parseFloat(this.calculateAverageGrade(s.grades)) < 70 ? ['Low academic performance'] : []), ...(s.attendance.percentage < 85 ? ['Poor attendance'] : []), ...(s.fees.pending > 0 ? ['Pending fees'] : [])]
    }));
  }
  async sendQuery(messages, schoolData, options = {}) {
    try {
      const cacheKey = this.generateCacheKey(messages);
      const cached = this.getFromCache(cacheKey);
      if (cached) return cached;
      const response = await fetch(this.apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.apiKey}`
        },
        body: JSON.stringify({
          model: options.model || 'llama2',
          messages: messages,
          max_tokens: options.maxTokens || 800,
          temperature: options.temperature || 0.3,
          top_p: options.topP || 0.9,
          frequency_penalty: 0.1,
          presence_penalty: 0.1,
          ...options
        })
      });
      if (!response.ok) {
        throw new Error(`API request failed: ${response.status} ${response.statusText}`);
      }
      const data = await response.json();
      const result = {
        content: data.choices[0].message.content,
        usage: data.usage,
        model: data.model,
        timestamp: new Date().toISOString()
      };
      this.cacheResponse(cacheKey, result);
      return result;
    } catch (error) {
      console.error('LLM query failed:', error);
      throw error;
    }
  }
  generateCacheKey(messages) {
    const lastMessage = messages[messages.length - 1];
    return btoa(lastMessage.content).slice(0, 20);
  }
  getFromCache(key) {
    const cached = this.responseCache.get(key);
    if (cached && Date.now() - cached.timestamp < this.cacheTimeout) {
      return cached.data;
    }
    if (cached) {
      this.responseCache.delete(key);
    }
    return null;
  }
  cacheResponse(key, data) {
    this.responseCache.set(key, {
      data,
      timestamp: Date.now()
    });

    // Clean old cache entries
    if (this.responseCache.size > 50) {
      const oldestKey = this.responseCache.keys().next().value;
      this.responseCache.delete(oldestKey);
    }
  }
  async processSchoolQuery(query, schoolData, conversationHistory = []) {
    try {
      // Extract relevant data based on query
      const relevantData = this.extractRelevantData(query, schoolData);

      // Create system prompt
      const systemPrompt = this.createSystemPrompt(schoolData);

      // Build messages array
      const messages = [{
        role: 'system',
        content: systemPrompt
      }];

      // Add recent conversation history (last 4 exchanges)
      const recentHistory = conversationHistory.slice(-8);
      messages.push(...recentHistory);

      // Add current query with context
      const contextualQuery = `${query}

Context Data:
${JSON.stringify(relevantData, null, 2)}

Please provide a comprehensive, helpful response based on this school data. Include specific insights, actionable recommendations, and relevant statistics.`;
      messages.push({
        role: 'user',
        content: contextualQuery
      });

      // Send to LLM
      const response = await this.sendQuery(messages, schoolData);
      return {
        success: true,
        response: response.content,
        usage: response.usage,
        relevantData,
        suggestions: this.generateSuggestions(query, relevantData)
      };
    } catch (error) {
      console.error('School query processing failed:', error);
      return {
        success: false,
        error: error.message,
        fallbackResponse: this.generateFallbackResponse(query, schoolData)
      };
    }
  }
  generateSuggestions(query, relevantData) {
    const suggestions = [];
    const lowerQuery = query.toLowerCase();
    if (relevantData.students) {
      suggestions.push('Show me top performing students', 'Which students need attention?', 'Generate attendance report');
    }
    if (relevantData.teachers) {
      suggestions.push('Show teacher performance ratings', 'What is the average teacher experience?', 'Compare teacher salaries by subject');
    }
    if (relevantData.finance) {
      suggestions.push('Show monthly revenue trends', 'Analyze expense breakdown', 'Generate financial health report');
    }
    if (relevantData.inventory) {
      suggestions.push('Show items needing reorder', 'Analyze inventory by category', 'Generate procurement report');
    }

    // Add general suggestions
    suggestions.push('Generate summary report', 'Show dashboard overview', 'What insights can you provide?');
    return suggestions.slice(0, 4);
  }
  generateFallbackResponse(query, schoolData) {
    const lowerQuery = query.toLowerCase();
    if (lowerQuery.includes('student')) {
      return `I'm having trouble connecting to the AI service, but I can tell you that we have ${schoolData.students.length} students enrolled. For detailed student information, please check the Students section.`;
    }
    if (lowerQuery.includes('teacher')) {
      return `I'm having trouble connecting to the AI service, but I can tell you that we have ${schoolData.teachers.length} teachers on staff. For detailed teacher information, please check the Teachers section.`;
    }
    if (lowerQuery.includes('finance')) {
      return `I'm having trouble connecting to the AI service, but I can tell you that our annual revenue is ₹${schoolData.finance.totalRevenue.toLocaleString()} with a net profit of ₹${schoolData.finance.netProfit.toLocaleString()}. For detailed financial information, please check the Finance section.`;
    }
    return `I'm having trouble connecting to the AI service right now. Please try again in a moment, or navigate to the relevant section for the information you need.`;
  }
  clearCache() {
    this.responseCache.clear();
  }
  getConnectionStatus() {
    return {
      connected: this.isConnected,
      apiUrl: this.apiUrl,
      hasApiKey: !!this.apiKey,
      cacheSize: this.responseCache.size
    };
  }
}
export default new LLMService();

