// src/services/llmService.js
class LLMService {
  constructor() {
    this.apiUrl = process.env.REACT_APP_LLM_API_URL || 'https://chat.ivislabs.in/api/v1/chat/completions';
    this.apiKey = process.env.REACT_APP_LLM_API_KEY;
    this.isConnected = false;
    this.responseCache = new Map();
    this.cacheTimeout = 5 * 60 * 1000; // 5 minutes
  }

  async testConnection() {
    try {
      const response = await fetch(this.apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.apiKey}`,
        },
        body: JSON.stringify({
          model: 'llama2',
          messages: [
            {
              role: 'user',
              content: 'Test connection. Reply with "OK".'
            }
          ],
          max_tokens: 5,
          temperature: 0.1
        })
      });

      this.isConnected = response.ok;
      return this.isConnected;
    } catch (error) {
      console.error('LLM connection test failed:', error);
      this.isConnected = false;
      return false;
    }
  }

  createSystemPrompt(schoolData) {
    return `You are EduCare AI, an intelligent assistant for Modern International School's ERP system. You help with school management tasks including student records, teacher management, finances, inventory, and analytics.

School Overview:
- Name: ${schoolData.school.name}
- Principal: ${schoolData.school.principal}
- Location: ${schoolData.school.address}
- Total Students: ${schoolData.students.length}
- Total Teachers: ${schoolData.teachers.length}
- Established: ${schoolData.school.established}
- Board: ${schoolData.school.board}

Key Guidelines:
1. Provide accurate, helpful responses about school data
2. Be professional, concise, and supportive
3. Give specific insights and actionable recommendations
4. Use clear formatting with bullet points when appropriate
5. Include relevant statistics and trends
6. Maintain student privacy while being informative
7. Focus on educational outcomes and school improvement

Response Format:
- Use markdown formatting for better readability
- Include relevant emojis for visual appeal
- Structure information with clear headings
- Provide specific numbers and percentages when available
- Suggest next steps or actions when appropriate

Available Data Categories:
- Students: Academic performance, attendance, fees, behavior
- Teachers: Performance, experience, subjects, salaries
- Finance: Revenue, expenses, profit margins, fee collection
- Inventory: Stock levels, categories, suppliers, reorder alerts
- Events: Upcoming activities, budget, participation
- Infrastructure: Facilities, equipment, maintenance`;
  }

  extractRelevantData(query, schoolData) {
    const lowerQuery = query.toLowerCase();
    const relevantData = {
      schoolInfo: {
        name: schoolData.school.name,
        totalStudents: schoolData.students.length,
        totalTeachers: schoolData.teachers.length
      }
    };

    // Student-related queries
    if (lowerQuery.includes('student') || lowerQuery.includes('pupil') || lowerQuery.includes('child')) {
      relevantData.students = schoolData.students.map(s => ({
        name: s.name,
        grade: s.grade,
        section: s.section,
        attendance: s.attendance.percentage,
        averageGrade: this.calculateAverageGrade(s.grades),
        behavior: s.behavior,
        feesPending: s.fees.pending,
        feesTotal: s.fees.annual,
        achievements: s.achievements.length,
        extracurricular: s.extracurricular.length
      }));

      // Add aggregated student stats
      relevantData.studentStats = this.calculateStudentStats(schoolData.students);
    }

    // Teacher-related queries
    if (lowerQuery.includes('teacher') || lowerQuery.includes('staff') || lowerQuery.includes('faculty')) {
      relevantData.teachers = schoolData.teachers.map(t => ({
        name: t.name,
        subject: t.subject,
        experience: t.experience,
        performance: t.performance,
        salary: t.salary,
        classes: t.classes.length,
        grades: t.grades
      }));

      relevantData.teacherStats = this.calculateTeacherStats(schoolData.teachers);
    }

    // Finance-related queries
    if (lowerQuery.includes('finance') || lowerQuery.includes('money') || lowerQuery.includes('fee') || 
        lowerQuery.includes('revenue') || lowerQuery.includes('expense') || lowerQuery.includes('budget')) {
      relevantData.finance = {
        totalRevenue: schoolData.finance.totalRevenue,
        totalExpenses: schoolData.finance.totalExpenses,
        netProfit: schoolData.finance.netProfit,
        profitMargin: ((schoolData.finance.netProfit / schoolData.finance.totalRevenue) * 100).toFixed(1),
        pendingFees: schoolData.finance.pendingFees,
        monthlyBreakdown: schoolData.finance.monthlyBreakdown,
        expenseCategories: schoolData.finance.expenseCategories,
        revenueStreams: schoolData.finance.revenueStreams
      };

      // Calculate fee collection rate
      const totalAnnualFees = schoolData.students.reduce((sum, s) => sum + s.fees.annual, 0);
      const totalPaidFees = schoolData.students.reduce((sum, s) => sum + s.fees.paid, 0);
      relevantData.finance.collectionRate = ((totalPaidFees / totalAnnualFees) * 100).toFixed(1);
    }

    // Inventory-related queries
    if (lowerQuery.includes('inventory') || lowerQuery.includes('stock') || lowerQuery.includes('equipment') || 
        lowerQuery.includes('supply') || lowerQuery.includes('item')) {
      relevantData.inventory = schoolData.inventory.map(item => ({
        item: item.item,
        category: item.category,
        quantity: item.quantity,
        minStock: item.minStock,
        needsReorder: item.quantity < item.minStock,
        totalValue: item.totalValue,
        supplier: item.supplier
      }));

      relevantData.inventoryStats = this.calculateInventoryStats(schoolData.inventory);
    }

    // Event-related queries
    if (lowerQuery.includes('event') || lowerQuery.includes('activity') || lowerQuery.includes('program')) {
      relevantData.events = schoolData.events.map(e => ({
        title: e.title,
        date: e.date,
        type: e.type,
        participants: e.participants,
        budget: e.budget,
        spent: e.spentAmount,
        status: e.status,
        coordinator: e.coordinator
      }));
    }

    // Performance/Analytics queries
    if (lowerQuery.includes('performance') || lowerQuery.includes('analytics') || lowerQuery.includes('report')) {
      relevantData.analytics = {
        studentPerformance: this.calculateStudentStats(schoolData.students),
        teacherPerformance: this.calculateTeacherStats(schoolData.teachers),
        financialHealth: this.calculateFinancialHealth(schoolData.finance),
        attendanceTrends: this.calculateAttendanceTrends(schoolData.students)
      };
    }

    return relevantData;
  }

  calculateAverageGrade(grades) {
    const values = Object.values(grades);
    return values.length > 0 ? (values.reduce((sum, grade) => sum + grade, 0) / values.length).toFixed(1) : 0;
  }

  calculateStudentStats(students) {
    const totalStudents = students.length;
    if (totalStudents === 0) return {};

    const avgAttendance = (students.reduce((sum, s) => sum + s.attendance.percentage, 0) / totalStudents).toFixed(1);
    const avgGrade = students.reduce((sum, s) => {
      const studentAvg = this.calculateAverageGrade(s.grades);
      return sum + parseFloat(studentAvg);
    }, 0) / totalStudents;

    const gradeDistribution = students.reduce((acc, s) => {
      acc[s.grade] = (acc[s.grade] || 0) + 1;
      return acc;
    }, {});

    const behaviorDistribution = students.reduce((acc, s) => {
      acc[s.behavior] = (acc[s.behavior] || 0) + 1;
      return acc;
    }, {});

    const feeStats = {
      totalPending: students.reduce((sum, s) => sum + s.fees.pending, 0),
      studentsWithPending: students.filter(s => s.fees.pending > 0).length,
      collectionRate: ((students.reduce((sum, s) => sum + s.fees.paid, 0) / 
                       students.reduce((sum, s) => sum + s.fees.annual, 0)) * 100).toFixed(1)
    };

    return {
      total: totalStudents,
      averageAttendance: avgAttendance,
      averageGrade: avgGrade.toFixed(1),
      gradeDistribution,
      behaviorDistribution,
      feeStats,
      topPerformers: this.getTopPerformers(students, 5),
      needsAttention: this.getStudentsNeedingAttention(students)
    };
  }

  calculateTeacherStats(teachers) {
    const totalTeachers = teachers.length;
    if (totalTeachers === 0) return {};

    const avgExperience = (teachers.reduce((sum, t) => sum + t.experience, 0) / totalTeachers).toFixed(1);
    const avgSalary = (teachers.reduce((sum, t) => sum + t.salary, 0) / totalTeachers).toFixed(0);

    const subjectDistribution = teachers.reduce((acc, t) => {
      acc[t.subject] = (acc[t.subject] || 0) + 1;
      return acc;
    }, {});

    const performanceDistribution = teachers.reduce((acc, t) => {
      acc[t.performance] = (acc[t.performance] || 0) + 1;
      return acc;
    }, {});

    const experienceRanges = {
      'New (0-2 years)': teachers.filter(t => t.experience <= 2).length,
      'Experienced (3-9 years)': teachers.filter(t => t.experience >= 3 && t.experience <= 9).length,
      'Senior (10+ years)': teachers.filter(t => t.experience >= 10).length
    };

    return {
      total: totalTeachers,
      averageExperience: avgExperience,
      averageSalary: avgSalary,
      subjectDistribution,
      performanceDistribution,
      experienceRanges,
      topPerformers: teachers.filter(t => t.performance === 'Outstanding' || t.performance === 'Excellent')
    };
  }

  calculateInventoryStats(inventory) {
    const totalItems = inventory.length;
    if (totalItems === 0) return {};

    const totalValue = inventory.reduce((sum, item) => sum + item.totalValue, 0);
    const lowStockItems = inventory.filter(item => item.quantity < item.minStock);
    const outOfStockItems = inventory.filter(item => item.quantity === 0);

    const categoryDistribution = inventory.reduce((acc, item) => {
      acc[item.category] = (acc[item.category] || 0) + 1;
      return acc;
    }, {});

    const categoryValues = inventory.reduce((acc, item) => {
      acc[item.category] = (acc[item.category] || 0) + item.totalValue;
      return acc;
    }, {});

    return {
      totalItems,
      totalValue,
      lowStockCount: lowStockItems.length,
      outOfStockCount: outOfStockItems.length,
      categoryDistribution,
      categoryValues,
      lowStockItems: lowStockItems.map(item => ({
        item: item.item,
        current: item.quantity,
        minimum: item.minStock,
        supplier: item.supplier
      }))
    };
  }

  calculateFinancialHealth(finance) {
    const profitMargin = ((finance.netProfit / finance.totalRevenue) * 100).toFixed(1);
    const revenueGrowth = this.calculateRevenueGrowth(finance.monthlyBreakdown);

    return {
      profitMargin,
      revenueGrowth,
      expenseRatio: ((finance.totalExpenses / finance.totalRevenue) * 100).toFixed(1),
      healthScore: this.calculateFinancialHealthScore(finance)
    };
  }

  calculateRevenueGrowth(monthlyData) {
    if (monthlyData.length < 2) return 0;
    const recent = monthlyData.slice(-3);
    const older = monthlyData.slice(-6, -3);

    const recentAvg = recent.reduce((sum, m) => sum + m.income, 0) / recent.length;
    const olderAvg = older.reduce((sum, m) => sum + m.income, 0) / older.length;

    return ((recentAvg - olderAvg) / olderAvg * 100).toFixed(1);
  }

  calculateFinancialHealthScore(finance) {
    const profitMargin = (finance.netProfit / finance.totalRevenue) * 100;
    if (profitMargin > 20) return 'Excellent';
    if (profitMargin > 15) return 'Good';
    if (profitMargin > 10) return 'Fair';
    return 'Needs Improvement';
  }

  calculateAttendanceTrends(students) {
    const attendanceRanges = {
      'Excellent (95%+)': students.filter(s => s.attendance.percentage >= 95).length,
      'Good (90-94%)': students.filter(s => s.attendance.percentage >= 90 && s.attendance.percentage < 95).length,
      'Fair (80-89%)': students.filter(s => s.attendance.percentage >= 80 && s.attendance.percentage < 90).length,
      'Poor (<80%)': students.filter(s => s.attendance.percentage < 80).length
    };

    return attendanceRanges;
  }

  getTopPerformers(students, count = 5) {
    return students
      .map(s => ({
        name: s.name,
        grade: s.grade,
        average: parseFloat(this.calculateAverageGrade(s.grades))
      }))
      .sort((a, b) => b.average - a.average)
      .slice(0, count);
  }

  getStudentsNeedingAttention(students) {
    return students.filter(s => {
      const avgGrade = parseFloat(this.calculateAverageGrade(s.grades));
      return avgGrade < 70 || s.attendance.percentage < 85 || s.fees.pending > 0;
    }).map(s => ({
      name: s.name,
      grade: s.grade,
      issues: [
        ...(parseFloat(this.calculateAverageGrade(s.grades)) < 70 ? ['Low academic performance'] : []),
        ...(s.attendance.percentage < 85 ? ['Poor attendance'] : []),
        ...(s.fees.pending > 0 ? ['Pending fees'] : [])
      ]
    }));
  }

  async sendQuery(messages, schoolData, options = {}) {
    try {
      const cacheKey = this.generateCacheKey(messages);
      const cached = this.getFromCache(cacheKey);
      if (cached) return cached;

      const response = await fetch(this.apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.apiKey}`,
        },
        body: JSON.stringify({
          model: options.model || 'llama2',
          messages: messages,
          max_tokens: options.maxTokens || 800,
          temperature: options.temperature || 0.3,
          top_p: options.topP || 0.9,
          frequency_penalty: 0.1,
          presence_penalty: 0.1,
          ...options
        })
      });

      if (!response.ok) {
        throw new Error(`API request failed: ${response.status} ${response.statusText}`);
      }

      const data = await response.json();
      const result = {
        content: data.choices[0].message.content,
        usage: data.usage,
        model: data.model,
        timestamp: new Date().toISOString()
      };

      this.cacheResponse(cacheKey, result);
      return result;

    } catch (error) {
      console.error('LLM query failed:', error);
      throw error;
    }
  }

  generateCacheKey(messages) {
    const lastMessage = messages[messages.length - 1];
    return btoa(lastMessage.content).slice(0, 20);
  }

  getFromCache(key) {
    const cached = this.responseCache.get(key);
    if (cached && Date.now() - cached.timestamp < this.cacheTimeout) {
      return cached.data;
    }
    if (cached) {
      this.responseCache.delete(key);
    }
    return null;
  }

  cacheResponse(key, data) {
    this.responseCache.set(key, {
      data,
      timestamp: Date.now()
    });

    // Clean old cache entries
    if (this.responseCache.size > 50) {
      const oldestKey = this.responseCache.keys().next().value;
      this.responseCache.delete(oldestKey);
    }
  }

  async processSchoolQuery(query, schoolData, conversationHistory = []) {
    try {
      // Extract relevant data based on query
      const relevantData = this.extractRelevantData(query, schoolData);

      // Create system prompt
      const systemPrompt = this.createSystemPrompt(schoolData);

      // Build messages array
      const messages = [
        { role: 'system', content: systemPrompt }
      ];

      // Add recent conversation history (last 4 exchanges)
      const recentHistory = conversationHistory.slice(-8);
      messages.push(...recentHistory);

      // Add current query with context
      const contextualQuery = `${query}

Context Data:
${JSON.stringify(relevantData, null, 2)}

Please provide a comprehensive, helpful response based on this school data. Include specific insights, actionable recommendations, and relevant statistics.`;

      messages.push({
        role: 'user',
        content: contextualQuery
      });

      // Send to LLM
      const response = await this.sendQuery(messages, schoolData);

      return {
        success: true,
        response: response.content,
        usage: response.usage,
        relevantData,
        suggestions: this.generateSuggestions(query, relevantData)
      };

    } catch (error) {
      console.error('School query processing failed:', error);
      return {
        success: false,
        error: error.message,
        fallbackResponse: this.generateFallbackResponse(query, schoolData)
      };
    }
  }

  generateSuggestions(query, relevantData) {
    const suggestions = [];
    const lowerQuery = query.toLowerCase();

    if (relevantData.students) {
      suggestions.push(
        'Show me top performing students',
        'Which students need attention?',
        'Generate attendance report'
      );
    }

    if (relevantData.teachers) {
      suggestions.push(
        'Show teacher performance ratings',
        'What is the average teacher experience?',
        'Compare teacher salaries by subject'
      );
    }

    if (relevantData.finance) {
      suggestions.push(
        'Show monthly revenue trends',
        'Analyze expense breakdown',
        'Generate financial health report'
      );
    }

    if (relevantData.inventory) {
      suggestions.push(
        'Show items needing reorder',
        'Analyze inventory by category',
        'Generate procurement report'
      );
    }

    // Add general suggestions
    suggestions.push(
      'Generate summary report',
      'Show dashboard overview',
      'What insights can you provide?'
    );

    return suggestions.slice(0, 4);
  }

  generateFallbackResponse(query, schoolData) {
    const lowerQuery = query.toLowerCase();

    if (lowerQuery.includes('student')) {
      return `I'm having trouble connecting to the AI service, but I can tell you that we have ${schoolData.students.length} students enrolled. For detailed student information, please check the Students section.`;
    }

    if (lowerQuery.includes('teacher')) {
      return `I'm having trouble connecting to the AI service, but I can tell you that we have ${schoolData.teachers.length} teachers on staff. For detailed teacher information, please check the Teachers section.`;
    }

    if (lowerQuery.includes('finance')) {
      return `I'm having trouble connecting to the AI service, but I can tell you that our annual revenue is ₹${schoolData.finance.totalRevenue.toLocaleString()} with a net profit of ₹${schoolData.finance.netProfit.toLocaleString()}. For detailed financial information, please check the Finance section.`;
    }

    return `I'm having trouble connecting to the AI service right now. Please try again in a moment, or navigate to the relevant section for the information you need.`;
  }

  clearCache() {
    this.responseCache.clear();
  }

  getConnectionStatus() {
    return {
      connected: this.isConnected,
      apiUrl: this.apiUrl,
      hasApiKey: !!this.apiKey,
      cacheSize: this.responseCache.size
    };
  }
}

export default new LLMService();
